import{_ as n,o as r,c as t,a2 as i}from"./chunks/framework.DBU8LMUS.js";const h=JSON.parse('{"title":"Komunitas & Grup","description":"","frontmatter":{"title":"Komunitas & Grup","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/grup.md","filePath":"latest/grup.md","lastUpdated":1786334463000}'),e={name:"latest/grup.md"};function l(u,a,s,o,d,g){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="komunitas-grup" tabindex="-1">Komunitas &amp; Grup <a class="header-anchor" href="#komunitas-grup" aria-label="Permalink to &quot;Komunitas &amp; Grup&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p><strong>Komunitas &amp; Grup</strong> adalah ruang bersama alumni berdasarkan <strong>angkatan</strong> atau <strong>minat</strong>. Setiap grup dilengkapi <strong>forum diskusi</strong> berisi thread dan balasan, layaknya media komunikasi forum pada umumnya, sehingga anggota dapat berdiskusi secara tertulis dan terstruktur.</p><h2 id="melihat-daftar-grup" tabindex="-1">Melihat Daftar Grup <a class="header-anchor" href="#melihat-daftar-grup" aria-label="Permalink to &quot;Melihat Daftar Grup&quot;">​</a></h2><ol><li>Klik menu <strong>Grup</strong> pada navigasi.</li><li>Halaman menampilkan kartu-kartu grup dengan informasi: <ul><li>Nama grup dan jenisnya (<strong>Angkatan</strong> atau <strong>Minat</strong>).</li><li>Deskripsi singkat.</li><li>Jumlah anggota.</li></ul></li><li>Klik kartu grup untuk membuka halaman detail.</li></ol><h2 id="bergabung-dengan-grup" tabindex="-1">Bergabung dengan Grup <a class="header-anchor" href="#bergabung-dengan-grup" aria-label="Permalink to &quot;Bergabung dengan Grup&quot;">​</a></h2><ol><li>Buka halaman detail grup.</li><li>Klik tombol <strong>Gabung</strong>.</li><li>Anda terdaftar sebagai anggota grup dan dapat mengikuti forum diskusinya.</li><li>Untuk keluar, klik tombol <strong>Keluar</strong> di halaman grup.</li></ol><h2 id="membuat-grup" tabindex="-1">Membuat Grup <a class="header-anchor" href="#membuat-grup" aria-label="Permalink to &quot;Membuat Grup&quot;">​</a></h2><h3 id="membuka-formulir" tabindex="-1">Membuka Formulir <a class="header-anchor" href="#membuka-formulir" aria-label="Permalink to &quot;Membuka Formulir&quot;">​</a></h3><ol><li>Pastikan Anda sudah masuk.</li><li>Klik tombol <strong>Buat Grup</strong> pada halaman <strong>Grup</strong>.</li><li>Anda akan diarahkan ke halaman pembuatan grup.</li></ol><h3 id="mengisi-formulir" tabindex="-1">Mengisi Formulir <a class="header-anchor" href="#mengisi-formulir" aria-label="Permalink to &quot;Mengisi Formulir&quot;">​</a></h3><ol><li>Isi <strong>nama grup</strong> (misalnya <code>Angkatan 2015</code> atau <code>Komunitas IoT</code>).</li><li>Pilih <strong>jenis grup</strong>: <strong>Angkatan</strong> atau <strong>Minat</strong>.</li><li>Tulis <strong>deskripsi</strong> grup.</li><li>Klik <strong>Simpan</strong>.</li></ol><h3 id="peran-pembuat-grup" tabindex="-1">Peran Pembuat Grup <a class="header-anchor" href="#peran-pembuat-grup" aria-label="Permalink to &quot;Peran Pembuat Grup&quot;">​</a></h3><p>Pembuat grup otomatis menjadi <strong>Admin Grup</strong> dan memiliki hak:</p><ul><li>Mengelola keanggotaan grup.</li><li>Menghapus thread atau balasan yang melanggar aturan.</li></ul><h2 id="menggunakan-forum-diskusi" tabindex="-1">Menggunakan Forum Diskusi <a class="header-anchor" href="#menggunakan-forum-diskusi" aria-label="Permalink to &quot;Menggunakan Forum Diskusi&quot;">​</a></h2><p>Forum diskusi grup memungkinkan anggota membuat thread dan membalas diskusi.</p><h3 id="membuat-thread" tabindex="-1">Membuat Thread <a class="header-anchor" href="#membuat-thread" aria-label="Permalink to &quot;Membuat Thread&quot;">​</a></h3><ol><li>Buka halaman grup, lalu bagian <strong>Diskusi</strong>.</li><li>Klik tombol <strong>Buat Thread</strong> atau <strong>Diskusi Baru</strong>.</li><li>Isi <strong>judul</strong> dan <strong>isi</strong> thread.</li><li>Klik <strong>Kirim</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Hak Akses</p><p>Hanya <strong>anggota grup</strong> yang dapat membuat thread dan membalas diskusi. Jika Anda belum bergabung, tombol pembuatan tidak tersedia.</p></div><h3 id="membalas-thread" tabindex="-1">Membalas Thread <a class="header-anchor" href="#membalas-thread" aria-label="Permalink to &quot;Membalas Thread&quot;">​</a></h3><ol><li>Buka thread yang ingin dibalas.</li><li>Gulir ke bagian balasan.</li><li>Tulis balasan Anda pada kolom yang tersedia.</li><li>Klik <strong>Kirim Balasan</strong>.</li></ol><h3 id="melihat-balasan" tabindex="-1">Melihat Balasan <a class="header-anchor" href="#melihat-balasan" aria-label="Permalink to &quot;Melihat Balasan&quot;">​</a></h3><p>Thread menampilkan balasan dalam urutan waktu. Setiap balasan menampilkan nama penulis dan waktu kirim.</p><h3 id="menghapus-thread-atau-balasan" tabindex="-1">Menghapus Thread atau Balasan <a class="header-anchor" href="#menghapus-thread-atau-balasan" aria-label="Permalink to &quot;Menghapus Thread atau Balasan&quot;">​</a></h3><p>Anda dapat menghapus thread atau balasan jika:</p><ul><li>Anda adalah <strong>penulis</strong> thread/balasan tersebut, atau</li><li>Anda adalah <strong>Admin Grup</strong> dari grup tersebut, atau</li><li>Anda adalah <strong>admin aplikasi</strong> dengan kemampuan moderasi grup.</li></ul><ol><li>Buka thread atau balasan yang ingin dihapus.</li><li>Klik tombol <strong>Hapus</strong>.</li><li>Konfirmasi penghapusan.</li></ol><h2 id="aturan-berdiskusi" tabindex="-1">Aturan Berdiskusi <a class="header-anchor" href="#aturan-berdiskusi" aria-label="Permalink to &quot;Aturan Berdiskusi&quot;">​</a></h2><ul><li>Gunakan bahasa yang sopan dan saling menghargai.</li><li>Jaga topik sesuai tujuan grup.</li><li>Jangan membagikan data pribadi orang lain tanpa izin.</li><li>Laporkan konten yang melanggar melalui tombol <strong>Laporkan</strong> yang tersedia.</li></ul><h2 id="peran-di-dalam-grup" tabindex="-1">Peran di Dalam Grup <a class="header-anchor" href="#peran-di-dalam-grup" aria-label="Permalink to &quot;Peran di Dalam Grup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Peran</th><th>Hak</th></tr></thead><tbody><tr><td><strong>Anggota</strong></td><td>Membuat thread, membalas, dan melihat seluruh diskusi.</td></tr><tr><td><strong>Admin Grup</strong></td><td>Hak anggota + menghapus thread/balasan dan mengelola keanggotaan.</td></tr><tr><td><strong>Admin Aplikasi</strong></td><td>Hak moderasi penuh atas grup (<code>moderate_groups</code>).</td></tr></tbody></table><p>Lanjutkan ke <a href="/webapps/latest/pengumuman">Pengumuman</a> untuk membaca informasi resmi dari komunitas.</p>',33)])])}const p=n(e,[["render",l]]);export{h as __pageData,p as default};
